    if index + 1 < length:
        return result
    samples = [paired(kind, i, closes[i]) for i in range(index + 1 - length, index + 1)]
    if any(a is None or b is None for a, b in samples):
        return result
    a = [Fraction.from_float(a) for a, _ in samples]
    b = [Fraction.from_float(b) for _, b in samples]
