    parser = argparse.ArgumentParser()
    parser.add_argument('--tag', choices=['before', 'after', 'both'], default='both')
    parser.add_argument('--prepare-only', action='store_true')
    args = parser.parse_args()
    prepare()
    if args.prepare_only:
        print('Prepared six paired sources; fifteen sources x four seeds x two modes = 120 public cases.')
        return
    specs = [{'source': f'stats-paired-{kind}.pine', 'kind': kind}
             for kind in ('shifted', 'realtime-na', 'dynamic', 'huge', 'tiny', 'orthogonal')]
    specs += [{'source': 'correlation-ordinary-cancellation.pine', 'kind': 'identical'},
              {'source': 'variance-overflow-tail-recovery.pine', 'kind': 'tail'}]
    specs += [{'source': 'stats-side-effects-named.pine', 'kind': 'named'},
              {'source': 'stats-subnormal-constant.pine', 'kind': 'subnormal'},
              {'source': 'edge-sum-overflow-tail.pine', 'kind': 'sum-positive'},
              {'source': 'edge-sum-negative-overflow-tail.pine', 'kind': 'sum-negative'},
              {'source': 'edge-sum-na-overflow-tail.pine', 'kind': 'sum-na'},
              {'source': 'edge-sum-finite-lost-tail.pine', 'kind': 'sum-finite'},
              {'source': 'edge-sum-dynamic-overflow-tail.pine', 'kind': 'sum-dynamic'}]
    tags = ('before', 'after') if args.tag == 'both' else (args.tag,)
    identities = {}
    for tag in tags:
        binary = D / f'differential-{tag}.exe'
        link_path = D / f'identity-differential-{tag}.json'
        link = json.loads(link_path.read_text(encoding='utf-8-sig'))
        assert sha(binary) == link['executableSha256']
        assert sha(D / 'differential.rs') == link['sourceSha256']
        identities[tag] = {'binary': str(binary), 'binarySha256': sha(binary),
                           'linkReceipt': link, 'linkReceiptSha256': sha(link_path)}
    run_id = datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%S.%fZ') + '-' + uuid.uuid4().hex[:8]
    out = D / 'statistics-correctness-receipts' / run_id
    out.mkdir(parents=True, exist_ok=False)
    receipt = {'status': 'running', 'tag': args.tag, 'runId': run_id,
               'runnerSha256': sha(Path(__file__)), 'identities': identities,
               'caseSpecs': specs, 'seeds': SEEDS, 'records': [],
               'oracle': 'Exact Fraction of representable Pine source floats, population centered moments. Rational variance-product division precedes sqrt.',
               'tailQualifier': 'Source checked on all bars. Original overflow-tail only statistics at bar_index >=3; sum-positive/negative >=3, sum-na >=5, sum-finite >=2, sum-dynamic >=5. Earlier overflowing/transition statistics outside this correction.'}
    try:
        for spec in specs:
            source = D / 'correctness' / spec['source']
            spec.update(sourceSha256=sha(source), sourceText=source.read_text(encoding='utf8'))
            for seed in SEEDS:
                for mode in ('unlimited', 'retained'):
                    for tag in tags:
                        command = [identities[tag]['binary'], str(source), mode, str(seed)]
                        process = subprocess.run(command, cwd=ROOT, capture_output=True, timeout=120)
                        stem = f'{source.stem}-{seed}-{mode}-{tag}'
                        stdout, stderr = out / f'{stem}.stdout', out / f'{stem}.stderr'
                        stdout.write_bytes(process.stdout)
                        stderr.write_bytes(process.stderr)
                        row = {'source': spec['source'], 'seedBars': seed, 'mode': mode, 'tag': tag,
                               'sourceSha256': sha(source), 'command': command, 'returncode': process.returncode,
                               'stdout': str(stdout), 'stderr': str(stderr), 'stdoutSha256': sha(stdout),
                               'stderrSha256': sha(stderr), 'mismatches': []}
                        receipt['records'].append(row)
                        assert process.returncode == 0 and not process.stderr, row
                        records = [json.loads(line) for line in process.stdout.splitlines()]
                        assert len(records) == 33 and records[0]['changes'] is None
                        assert all(isinstance(record['changes'], dict) for record in records[1:])
                        closes = {i: close_value(i, .25) for i in range(seed)}
                        cache = {i: expected(spec['kind'], i, closes) for i in range(seed)} if spec['kind'] not in ('identical', 'tail') else {}
                        checked, mismatches, skipped = 0, 0, 0
                        for ordinal, record in enumerate(records):
                            latest = seed - 1 if ordinal == 0 else seed + (ordinal - 1) // 4
                            if ordinal:
                                closes[latest] = close_value(latest, OFFSETS[(ordinal - 1) % 4])
                                if spec['kind'] not in ('identical', 'tail'):
                                    cache[latest] = expected(spec['kind'], latest, closes)
                            plots = {plot['title']: plot['values'] for plot in record['snapshot']['plots']}
                            if spec['kind'] in ('identical', 'tail'):
                                expected_titles = {'source', 'identical_correlation', 'centered_variance'} if spec['kind'] == 'identical' else {'source', 'variance', 'stdev', 'bb_basis', 'bb_upper', 'bb_lower'}
                            else:
                                expected_titles = set(cache[latest]) - {'_threshold'}
                            assert set(plots) == expected_titles, (row, plots.keys())
                            lengths = {len(values) for values in plots.values()}
                            assert len(lengths) == 1 and next(iter(lengths)) > 0
                            for title, values in plots.items():
                                first = latest + 1 - len(values)
                                for local, actual in enumerate(values):
                                    index = first + local
                                    if spec['kind'] == 'identical':
                                        target = (1e8 + index % 2) if title == 'source' else (None if index == 0 else (1.0 if title == 'identical_correlation' else .25))
                                    elif spec['kind'] == 'tail':
                                        if title == 'source':
                                            target = 1e308 if index < 2 else 1.0
                                        elif index < 3:
                                            skipped += 1
                                            continue
                                        else:
                                            target = 0.0 if title in ('variance', 'stdev') else 1.0
                                    else:
                                        if title != 'source' and spec['kind'].startswith('sum-') and index < cache[index]['_threshold']:
                                            skipped += 1
                                            continue
                                        target = cache[index][title]
                                    checked += 1
                                    if not match(actual, target):
                                        mismatches += 1
                                        if len(row['mismatches']) < 12:
                                            row['mismatches'].append({'snapshot': ordinal, 'barIndex': index, 'plot': title, 'actual': actual, 'expected': target})
                        row.update(status='observed-before' if tag == 'before' else 'passed',
                                   snapshots=33, deltas=32, qualifiedValues=checked,
                                   mismatchValues=mismatches, unqualifiedEarlyTailValues=skipped)
                        assert tag == 'before' or mismatches == 0, row
                        assert sha(source) == row['sourceSha256']
        for identity in identities.values():
            assert sha(Path(identity['binary'])) == identity['binarySha256']
        receipt.update(status='passed', publicCases=len(specs) * len(SEEDS) * 2,
                       processes=len(receipt['records']), snapshotsPerVersion=33 * len(specs) * len(SEEDS) * 2,
                       deltasPerVersion=32 * len(specs) * len(SEEDS) * 2,
                       mismatchValuesByTag={tag: sum(row['mismatchValues'] for row in receipt['records'] if row['tag'] == tag) for tag in tags})
    except BaseException as error:
        receipt.update(status='failed', error=repr(error))
        raise
    finally:
        path = out / 'summary.json'
        raw = json.dumps(receipt, indent=2, allow_nan=False).encode('utf8')
        path.write_bytes(raw)
        (D / f'statistics-correctness-{args.tag}-results.json').write_bytes(raw)
    print(json.dumps({'status': receipt['status'], 'processes': receipt['processes'],
                      'publicCases': receipt['publicCases'], 'mismatches': receipt['mismatchValuesByTag'],
                      'summary': str(path), 'sha256': sha(path)}), flush=True)


if __name__ == '__main__':
    main()

