    }


def preserved_history() -> list[dict]:
    entries = []
    for path in PRIOR:
        data = json.loads(path.read_text(encoding="utf8"))
        records = data["records"] if "records" in data else [data]
        files = {}
        for row in records:
            for kind in ("stdout", "stderr", "exit"):
                raw_path = Path(row[kind] if kind in row else row[kind + "Receipt"])
