def analyze(case: str, seed: int, raw: bytes) -> dict:
    lines = raw.splitlines()
    if len(lines) != 33 or any(not line for line in lines):
        raise ValueError("Expected 33 nonempty full snapshot/change records")
    records = [decode(line) for line in lines]
    for index, record in enumerate(records):
        if not isinstance(record, dict) or set(record) != {"snapshot", "changes"}:
            raise ValueError("Unexpected snapshot/change schema")
        if not isinstance(record["snapshot"], dict):
            raise ValueError("Snapshot is not an object")
        if (index == 0 and record["changes"] is not None) or (
                index != 0 and not isinstance(record["changes"], dict)):
            raise ValueError("Expected initial snapshot then 32 complete deltas")

    failures = []
    checked = 0
    latest = {}
    for record_index, record in enumerate(records):
        last_index = seed - 1 if record_index == 0 else seed + (record_index - 1) // 4
        plots_list = record["snapshot"]["plots"]
        plots = {plot["title"]: plot["values"] for plot in plots_list}
        if len(plots) != len(plots_list) or set(plots) != set(targets(case, last_index)):
            raise ValueError("Duplicate or unexpected plot titles")
