    if any(value is not None for title, values in latest.items() if title != "x" for value in values[:warmup]):
        raise ValueError("Warmup behavior differs; this is outside the selected residual diagnostic")
    if case == "finite_raw_moment":
        if any(not close(actual, targets(case, i)["x"]) for i, actual in enumerate(latest["x"])):
            raise ValueError("Declared source samples differ; cannot attribute an aggregate defect")
        failed_bars = sorted({failure["barIndex"] for failure in failures
                              if failure["snapshotIndex"] == len(records) - 1 and failure["barIndex"] >= warmup})
        finite_values = {title: [number(value) for value in latest[title][warmup:]]
                         for title in ("corr", "cov", "variance")}
        if any(value is None for values in finite_values.values() for value in values):
            raise ValueError("Finite raw-moment residual unexpectedly became NA")
        corr_last, cov_last = finite_values["corr"][-1], finite_values["cov"][-1]
        extra = {
            "independentPopulationVariance": 5504.0, "varianceDirectlyPlotted": True,
            "lastImpliedDenominator": cov_last / corr_last if corr_last else None,
            "observedFiniteRanges": {title: [min(values), max(values)] for title, values in finite_values.items()},
            "uniqueFailedBarsInLatestSnapshot": failed_bars,
            "expectedResidual": "At least one finite correlation/covariance fails corr=1/cov=5504 after warmup",
            "residualConfirmed": bool(failed_bars),
        }
    else:
        actual_na = all(value is None for values in latest.values() for value in values[warmup:])
        extra = {
            "expectedActualGap": {"wma": None, "hma": None},
            "independentFiniteConstant": 1e308,
            "residualConfirmed": actual_na and bool(failures),
            "expectedResidual": "WMA/HMA remain NA after warmup although their constant mathematical value is finite",
        }
