        "serializedValueChecks": checked, "independentMathFailures": len(failures),
        "mathStatus": "failed" if failures else "passed",
        "diagnosticStatus": "residual_confirmed" if extra["residualConfirmed"] else "residual_not_confirmed",
        "failures": failures,
        "lastValues": {title: values[-8:] for title, values in latest.items()},
        "recordSha256": [hashlib.sha256(line).hexdigest() for line in lines],
        **extra,
    }


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--timeout", type=float, default=120)
    args = parser.parse_args()
    # Check both versions before starting ANY process. Parent links the final
    # after executable only after all production gates and source freeze.
    identities = {tag: identity(tag) for tag in TAGS}
    if identities["before"]["probeSourceSha256"] != identities["after"]["probeSourceSha256"]:
        raise RuntimeError("Before and after probes were linked from different source")
    prior = preserved_history()
    source_receipts = {
        name: {"path": str(D / "correctness/remaining" / name),
               "sha256": sha(D / "correctness/remaining" / name)}
        for _, name, _ in CASES
    }
    stamp = datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%S.%fZ") + "-" + uuid.uuid4().hex[:8]
    out = D / "remaining-diagnostic-receipts" / stamp
    out.mkdir(parents=True, exist_ok=False)
    rows = []
    receipt = {
        "status": "running", "method": "Two excluded sources, unlimited mode, one fresh process per source/version",
        "scope": "Residual diagnosis only; excluded from ordinary parity and qualified repair-math denominators",
        "plannedProcesses": 4, "plannedSnapshots": 132, "plannedDeltas": 128,
        "runner": str(Path(__file__)), "runnerSha256": sha(Path(__file__)),
        "identities": identities, "sources": source_receipts, "preservedPriorReceipts": prior, "records": rows,
        "probeAssertions": {"ownedView": "32 updates per process", "confirmedOwnedView": "32 updates per process",
                            "replica": "32 updates per process; initial snapshot is also emitted",
                            "enabledBy": "--cfg borrowed_result, verified in both linked receipts"},
    }
    try:
        for case, name, seed in CASES:
            for tag in TAGS:
                command = [identities[tag]["binary"], source_receipts[name]["path"], "unlimited", str(seed)]
                stem = f"{case}-{tag}"
                row = {"case": case, "tag": tag, "mode": "unlimited", "seedBars": seed,
                       "command": command, "commandSha256": hashlib.sha256(json.dumps(command, separators=(",", ":")).encode()).hexdigest(),
                       "binarySha256": identities[tag]["binarySha256"], "sourceSha256": source_receipts[name]["sha256"]}
                try:
                    process = subprocess.run(command, cwd=ROOT, capture_output=True, timeout=args.timeout)
                    raw, errors, code = process.stdout, process.stderr, process.returncode
                except subprocess.TimeoutExpired as error:
                    raw, errors, code = error.stdout or b"", error.stderr or b"", None
                    row["timeoutSeconds"] = args.timeout
                stdout, stderr, exit_path = (out / f"{stem}{suffix}" for suffix in (".stdout", ".stderr", ".exit.json"))
                stdout.write_bytes(raw)
                stderr.write_bytes(errors)
                save(exit_path, {"command": command, "returncode": code})
                row.update(returncode=code, stdoutReceipt=str(stdout), stderrReceipt=str(stderr), exitReceipt=str(exit_path),
                           stdoutSha256=sha(stdout), stderrSha256=sha(stderr), exitSha256=sha(exit_path))
                rows.append(row)
                if code != 0:
                    row["status"] = "process_failed"
                else:
                    try:
                        row["analysis"] = analyze(case, seed, raw)
                        row["status"] = "diagnostics_collected"
                    except Exception as error:
                        row.update(status="analysis_failed", error=repr(error))
                save(out / f"{stem}.execution.json", row)
                save(out / "progress.json", receipt)
                print(case, tag, row["status"], row.get("analysis", {}).get("diagnosticStatus"), flush=True)
        for tag in TAGS:
            if identity(tag) != identities[tag]:
                raise RuntimeError(f"Linked probe identity changed during diagnosis: {tag}")
        for source in source_receipts.values():
            if sha(Path(source["path"])) != source["sha256"]:
                raise RuntimeError("Diagnostic source changed during execution")
        if preserved_history() != prior or sha(Path(__file__)) != receipt["runnerSha256"]:
            raise RuntimeError("Prior raw receipts or diagnostic runner changed")
        operational_failures = [row for row in rows if row["status"] != "diagnostics_collected"]
        receipt.update(status="diagnostics_collected" if not operational_failures else "failed",
                       completedProcesses=len(rows),
                       snapshots=sum(row.get("analysis", {}).get("snapshots", 0) for row in rows),
                       deltas=sum(row.get("analysis", {}).get("deltas", 0) for row in rows),
                       independentMathPassedProcesses=sum(row.get("analysis", {}).get("mathStatus") == "passed" for row in rows),
                       independentMathFailedProcesses=sum(row.get("analysis", {}).get("mathStatus") == "failed" for row in rows),
                       residualConfirmedProcesses=sum(row.get("analysis", {}).get("residualConfirmed", False) for row in rows),
                       operationalFailures=operational_failures)
        if operational_failures or len(rows) != 4:
            raise RuntimeError("Residual diagnostic transport/schema failed; all raw receipts are retained")
    except BaseException as error:
        receipt.update(status="failed", error=repr(error), completedProcesses=len(rows))
        raise
    finally:
        save(out / "summary.json", receipt)
        save(D / "remaining-diagnostics-results.json", receipt)
    print("COLLECTED", len(rows), "excluded residual diagnostics;",
          receipt["independentMathFailedProcesses"], "processes failed independent math;",
          out / "summary.json", flush=True)


if __name__ == "__main__":
    main()

link_probe.ps1.text:
param(
    [ValidateSet('before','after')] [string] $Tag,
    [ValidateSet('dispatch','result','heap','differential','delta_reference','delta')] [string] $Probe
)
$ErrorActionPreference = 'Stop'
Set-Location -LiteralPath 'E:\projects\pine-interpreter'
$probeDirectory = '.local/statistics-qr-20261004'
$libraryDirectory = if ($Tag -eq 'before') { "$probeDirectory/baseline" } else { 'target/release' }
$sources = @{ delta = "$probeDirectory/delta_probe.rs"; delta_reference = "$probeDirectory/delta_reference.rs"; dispatch = "$probeDirectory/dispatch_probe.rs"; result = "$probeDirectory/result_probe.rs"; heap = "$probeDirectory/heap_probe.rs"; differential = "$probeDirectory/differential.rs" }
$vswhere = Join-Path ${env:ProgramFiles(x86)} 'Microsoft Visual Studio/Installer/vswhere.exe'
$installation = (& $vswhere -latest -products '*' -requires Microsoft.VisualStudio.Component.VC.Tools.x86.x64 -property installationPath | Select-Object -First 1)
Import-Module (Join-Path $installation 'Common7/Tools/Microsoft.VisualStudio.DevShell.dll')
Enter-VsDevShell -VsInstallPath $installation -SkipAutomaticLocation -DevCmdArguments '-arch=amd64' | Out-Null
$libraryPaths = @("$libraryDirectory/libpine_runtime.rlib", "$libraryDirectory/libpine_sema.rlib", "$libraryDirectory/libpine_syntax.rlib", "$libraryDirectory/deps/libserde_json-ff9aee5763d82a17.rlib")
$hashes = @{}
foreach ($path in $libraryPaths) { $hashes[$path] = (Get-FileHash -LiteralPath $path -Algorithm SHA256).Hash.ToLower() }
$arguments = @('--edition=2024', '-O', '-C', 'lto=thin', '-C', 'codegen-units=1', '-L', "dependency=$libraryDirectory/deps", '--extern', "pine_runtime=$libraryDirectory/libpine_runtime.rlib", '--extern', "pine_sema=$libraryDirectory/libpine_sema.rlib", '--extern', "pine_syntax=$libraryDirectory/libpine_syntax.rlib", '--extern', "serde_json=$libraryDirectory/deps/libserde_json-ff9aee5763d82a17.rlib")
if ($Probe -in @('result', 'differential')) { $arguments += @('--cfg', 'borrowed_result') }
if ($Tag -eq 'after' -and $Probe -eq 'delta') { $arguments += @('--cfg', 'delta_sink') }
$ErrorActionPreference = 'Continue'
& rustc $sources[$Probe] @arguments -o "$probeDirectory/$Probe-$Tag.exe" *> "$probeDirectory/link-$Probe-$Tag.log"
if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
$ErrorActionPreference = 'Stop'
foreach ($path in $libraryPaths) { if ((Get-FileHash -LiteralPath $path -Algorithm SHA256).Hash.ToLower() -ne $hashes[$path]) { throw "Library changed while linking: $path" } }
@{
    tag = $Tag
    probe = $Probe
    libraryHashes = $hashes
    executableSha256 = (Get-FileHash -LiteralPath "$probeDirectory/$Probe-$Tag.exe" -Algorithm SHA256).Hash.ToLower()
    sourceSha256 = (Get-FileHash -LiteralPath $sources[$Probe] -Algorithm SHA256).Hash.ToLower()
    compilerArguments = $arguments
    rustc = (& rustc -V)
} | ConvertTo-Json -Depth 8 | Set-Content "$probeDirectory/identity-$Probe-$Tag.json" -Encoding utf8
exit 0

